    var ex=0;(io.out||[]).forEach(function(e,ei){var v=Math.round(Math.max(0,H.interp(P.course[e.k]||[[0,0]],H.days(P.admit,x[1])/P.f))*hh/12*(1+.25*H.noise(P.id+e.k+x[2].getTime()))/5)*5;extra[ei].push(v);ex+=v;});
