  if(pop==='peds'||pop==='neonate'||pop==='psych'||P.person.ageY>=82)want.sw=1;if(pop==='ob'||pop==='neonate')want.lact=1;if(P.comp&&P.comp.key==='ssi')want.wound=1;if(P.flags.renal||P.flags.anticoag||P.los>3)want.pharm2=1;
